fn seedSwarm(index: u32) {
    let base = index * B_swarm_STRIDE;
    let col = f32(index % 1024u);
    let row = f32(index / 1024u);
    let half = f32(1023u) * 0.5;
    b_swarm[base + 0u] = 0.0;
    b_swarm[base + 1u] = (col - half) * 0.029296875;
    b_swarm[base + 2u] = 0.0;
    b_swarm[base + 3u] = (row - half) * 0.029296875;
    b_swarm[base + 4u] = 0.0;
    b_swarm[base + 5u] = 0.0;
    b_swarm[base + 6u] = 0.0;
    b_swarm[base + 7u] = 1.0;
    b_swarm[base + 8u] = 1;
    b_swarm[base + 9u] = 1;
    b_swarm[base + 10u] = 1;
    b_swarm[base + 11u] = 0.55 + 0.4 * fract(col * 0.37);
    b_swarm[base + 12u] = 0.55 + 0.4 * fract(row * 0.29);
    b_swarm[base + 13u] = 0.7;
}

fn turnSwarm(index: u32) {
    let base = index * B_swarm_STRIDE;
    let half = 0.5 * (sim.time + f32(index % 97u) * 0.1);
    b_swarm[base + 4u] = 0.0;
    b_swarm[base + 5u] = sin(half);
    b_swarm[base + 6u] = 0.0;
    b_swarm[base + 7u] = cos(half);
}
